-- PRJ-02 templates v2 (23/10): lean templates — decisions people take, and the deliverables S.A.M. opens and follows by itself
-- (manual revisions, authority files, certificates). Forms, checklists, LEP, organisation chart and attachments are checked in
-- the authority file's own checklist (second-round causes seen in 226 TM-CAD and 391 METEOR files), never duplicated here.

insert into project_templates (code, name, description, entities, phases, tasks, pivots, ord, active) values
('AC-NEW', 'Aircraft addition — new type in CAT', 'Addition of a new aircraft type under the AOC. Five stages, thirty lines: a few decisions, then the manuals, authority files and certificates S.A.M. opens and follows by itself. Forms, compliance checklists, LEP, organisation chart and attachments are checked in each authority file before submission (TM-CAD / METEOR second-round causes).', array['AJD','ASJ']::entity_code[],
 '[{"key": "frame", "label": "1 · Decide"}, {"key": "acft", "label": "2 · Aircraft & registration"}, {"key": "aw", "label": "3 · Airworthiness"}, {"key": "ops", "label": "4 · Operations & training"}, {"key": "eis", "label": "5 · Entry into service"}]'::jsonb,
 '[{"key": "go", "phase": "frame", "title": "Go: aircraft, registration, target entry-into-service date", "owner_role": "AM", "days": 1, "deps": []}, {"key": "contract", "phase": "frame", "title": "Purchase / lease and management contracts signed", "owner_role": "AM", "days": 10, "deps": ["go"]}, {"key": "scope", "phase": "frame", "title": "Operational scope decided: SPA (RVSM, NAT HLA, LVO, steep approach, PBN, DG…), bases, EFB, simulator", "owner_role": "NPFO", "days": 2, "deps": ["go"], "detail": "Every YES becomes a line of the SPA application; CMPA check sets the airworthiness route (OAN 02/16)"}, {"key": "moc", "phase": "frame", "title": "MOC + risk assessment (operations and airworthiness)", "owner_role": "SM", "days": 3, "deps": ["scope"]}, {"key": "ppi", "phase": "acft", "title": "Pre-purchase inspection, records review, control flight", "owner_role": "NPCA", "days": 6, "deps": ["contract"]}, {"key": "docs", "phase": "acft", "title": "Manufacturer documentation access (evidence kept for the applications)", "owner_role": "NPCA", "days": 3, "deps": ["contract"]}, {"key": "reg", "phase": "acft", "title": "Registration", "owner_role": "NPCA", "days": 10, "deps": ["contract"], "link_kind": "authority_file", "link_ref": "AW-CERT"}, {"key": "cofa", "phase": "acft", "title": "Certificate of Airworthiness / ARC", "owner_role": "NPCA", "days": 10, "deps": ["reg", "ppi"], "link_kind": "certificate", "link_ref": "CofA"}, {"key": "radio", "phase": "acft", "title": "Radio licence", "owner_role": "NPCA", "days": 5, "deps": ["reg"], "link_kind": "certificate", "link_ref": "radio"}, {"key": "insur", "phase": "acft", "title": "Insurance", "owner_role": "NPGO", "days": 5, "deps": ["contract"], "link_kind": "certificate", "link_ref": "insurance"}, {"key": "dsac_out", "phase": "acft", "title": "If the aircraft leaves the French AOC: DSAC removal", "owner_role": "CMM", "days": 1, "deps": ["go"], "link_kind": "authority_file", "link_ref": "AC-OUT"}, {"key": "came", "phase": "aw", "title": "CAME — type added", "owner_role": "NPCA", "days": 10, "deps": ["docs", "moc"], "link_kind": "manual", "link_ref": "CAME"}, {"key": "amp", "phase": "aw", "title": "AMP for the type", "owner_role": "NPCA", "days": 10, "deps": ["docs"], "link_kind": "manual", "link_ref": "AMP"}, {"key": "app_camo", "phase": "aw", "title": "Part-CAMO variation", "owner_role": "CMM", "days": 1, "deps": ["came", "reg", "moc"], "link_kind": "authority_file", "link_ref": "CAMO-VAR"}, {"key": "app_came", "phase": "aw", "title": "CAME approval", "owner_role": "CMM", "days": 1, "deps": ["came"], "link_kind": "authority_file", "link_ref": "CAME"}, {"key": "app_amp", "phase": "aw", "title": "AMP approval", "owner_role": "CMM", "days": 1, "deps": ["amp"], "link_kind": "authority_file", "link_ref": "AMP"}, {"key": "msm", "phase": "ops", "title": "MSM — fleet and scope", "owner_role": "CMM", "days": 5, "deps": ["scope"], "link_kind": "manual", "link_ref": "MSM"}, {"key": "om_a", "phase": "ops", "title": "OM-A — type, SPA, organisation", "owner_role": "NPFO", "days": 10, "deps": ["scope"], "link_kind": "manual", "link_ref": "OM-A"}, {"key": "om_b", "phase": "ops", "title": "OM-B — type procedures", "owner_role": "NPFO", "days": 10, "deps": ["docs"], "link_kind": "manual", "link_ref": "OM-B"}, {"key": "mel", "phase": "ops", "title": "MEL for the type", "owner_role": "NPFO", "days": 5, "deps": ["docs"], "link_kind": "manual", "link_ref": "MEL"}, {"key": "om_c", "phase": "ops", "title": "OM-C — routes and aerodromes", "owner_role": "NPFO", "days": 10, "deps": ["scope"], "link_kind": "manual", "link_ref": "OM-C"}, {"key": "om_d", "phase": "ops", "title": "OM-D — type training, LIFUS, SPA training", "owner_role": "NPCT", "days": 10, "deps": ["scope"], "link_kind": "manual", "link_ref": "OM-D"}, {"key": "efb", "phase": "ops", "title": "EFB manual", "owner_role": "NPFO", "days": 4, "deps": ["om_a", "om_b", "om_c"], "link_kind": "manual", "link_ref": "EFB"}, {"key": "fstd", "phase": "ops", "title": "Simulator approval (if a device is used)", "owner_role": "CMM", "days": 1, "deps": ["om_d"], "link_kind": "authority_file", "link_ref": "FSTD"}, {"key": "crew", "phase": "ops", "title": "Crew licences, medicals and SPA training recorded", "owner_role": "NPCT", "days": 15, "deps": ["om_d"]}, {"key": "app_ops", "phase": "ops", "title": "OPS addition of the aircraft — one application (OM-A/B/C/D, MSM, MEL, EFB)", "owner_role": "CMM", "days": 1, "deps": ["om_a", "om_b", "om_c", "om_d", "msm", "mel", "efb", "reg", "cofa", "insur", "app_camo"], "link_kind": "authority_file", "link_ref": "AC-NEW"}, {"key": "app_spa", "phase": "ops", "title": "Specific approvals — one application, one line per SPA", "owner_role": "CMM", "days": 1, "deps": ["om_b", "om_d"], "link_kind": "authority_file", "link_ref": "SPA"}, {"key": "opspecs", "phase": "eis", "title": "Operations specifications received", "owner_role": "CMM", "days": 1, "deps": ["app_ops", "app_spa"], "link_kind": "certificate", "link_ref": "OpSpecs"}, {"key": "systems", "phase": "eis", "title": "Fleet systems live: Leon, EFB, FDM, TrustFlight, OFP", "owner_role": "NPFO", "days": 2, "deps": ["opspecs"]}, {"key": "eis", "phase": "eis", "title": "Entry into service — first commercial flight", "owner_role": "AM", "days": 1, "deps": ["opspecs", "systems", "crew"]}, {"key": "close", "phase": "eis", "title": "Close-out: approvals filed, fees recorded, lessons learned pushed to the template", "owner_role": "CMM", "days": 1, "deps": ["eis"]}]'::jsonb,
 array['aircraft_type','aircraft_reg']::text[], 1, true)
