update authority_file_types set checklist = '[{"key": "g_rev", "label": "OM-A/B/C/D, MSM, MEL, EFB revised with the type; each compliance checklist at the same revision as its manual", "role": "NP", "required": true}, {"key": "g_lep", "label": "LEP and revision bars refreshed; no residue of a removed type anywhere", "role": "NP", "required": true}, {"key": "g_org", "label": "Organisation chart and nominated persons up to date (OM-A A.01, MSM)", "role": "CMM", "required": true}, {"key": "forms", "label": "AOC variation form and OM approval form signed", "role": "CMM", "required": true}, {"key": "docs", "label": "Registration, CofA, radio licence, insurance and CAMO scope attached or referenced", "role": "CMM", "required": true}, {"key": "moc", "label": "MOC / risk assessment attached", "role": "SM", "required": true}, {"key": "g_pack", "label": "Manual PDFs exported from S.A.M., checklists, EFB checklist, OFP + ATC FPL samples, FDM agreement attached", "role": "CMM", "required": true}]'::jsonb where code = 'AC-NEW';
-- the five dossier checks appended to the other application types when they are not there yet
update authority_file_types set checklist = checklist || '[{"key": "g_rev", "label": "Compliance checklist(s) at the same revision as the manual(s) submitted", "role": "CMM", "required": true}]'::jsonb where code = 'OM-APP' and not exists (select 1 from jsonb_array_elements(checklist) e where e->>'key' = 'g_rev');
update authority_file_types set checklist = checklist || '[{"key": "g_lep", "label": "LEP and revision bars refreshed; no residue of a removed type or old name", "role": "NP", "required": true}]'::jsonb where code = 'OM-APP' and not exists (select 1 from jsonb_array_elements(checklist) e where e->>'key' = 'g_lep');
update authority_file_types set checklist = checklist || '[{"key": "g_org", "label": "Organisation chart and nominated persons up to date in the manual", "role": "CMM", "required": true}]'::jsonb where code = 'OM-APP' and not exists (select 1 from jsonb_array_elements(checklist) e where e->>'key' = 'g_org');
update authority_file_types set checklist = checklist || '[{"key": "g_sign", "label": "Forms and signature pages signed (Administration & Control / DocuSign)", "role": "CMM", "required": true}]'::jsonb where code = 'OM-APP' and not exists (select 1 from jsonb_array_elements(checklist) e where e->>'key' = 'g_sign');
update authority_file_types set checklist = checklist || '[{"key": "g_pack", "label": "Attachments complete: manual PDF, checklist, MOC / RA, forms, evidence", "role": "CMM", "required": true}]'::jsonb where code = 'OM-APP' and not exists (select 1 from jsonb_array_elements(checklist) e where e->>'key' = 'g_pack');
update authority_file_types set checklist = checklist || '[{"key": "g_rev", "label": "Compliance checklist(s) at the same revision as the manual(s) submitted", "role": "CMM", "required": true}]'::jsonb where code = 'OM-NOT' and not exists (select 1 from jsonb_array_elements(checklist) e where e->>'key' = 'g_rev');
